object ServiceRegistry {
  private val services =
    scala.collection.concurrent.TrieMap.empty[String, Service]

  def register(name: String, service: Service): Unit =
    require(services.putIfAbsent(name, service).isEmpty,
      s"duplicate service: $name")

  def lookup(name: String): Service =
    services.getOrElse(name,
      throw new NoSuchElementException(s"unknown service: $name"))
}
